using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Controls;
public sealed class UcDashboard:UserControl { private readonly IBetaFitApiService _api; private readonly UcStatCard a=new("Produtos"),b=new("Produtos ativos"),c=new("Em destaque"),d=new("Categorias"),e=new("Categorias ativas"); private readonly Label status=new(); public UcDashboard(IBetaFitApiService api){_api=api;Dock=DockStyle.Fill;BackColor=Color.FromArgb(15,18,23);Padding=new Padding(28);var title=new Label{Text="Dashboard",Dock=DockStyle.Top,Height=50,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",22)};var grid=new TableLayoutPanel{Dock=DockStyle.Top,Height=170,ColumnCount=5};for(int i=0;i<5;i++)grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,20));grid.Controls.Add(a,0,0);grid.Controls.Add(b,1,0);grid.Controls.Add(c,2,0);grid.Controls.Add(d,3,0);grid.Controls.Add(e,4,0);status.Text="Carregando...";status.ForeColor=Color.Silver;status.Dock=DockStyle.Top;status.Height=35;Controls.Add(status);Controls.Add(grid);Controls.Add(title);Load+=async(_,_)=>await RefreshAsync();} private async Task RefreshAsync(){try{status.Text="Consultando API...";var x=await _api.GetDashboardSummaryAsync();a.SetValue(x.TotalProducts);b.SetValue(x.ActiveProducts);c.SetValue(x.FeaturedProducts);d.SetValue(x.TotalCategories);e.SetValue(x.ActiveCategories);status.Text="Dados atualizados.";}catch(Exception ex){status.Text=ex.Message;}} }